// The one-line summary shown beside a quote, with the last day it can be accepted.
export function summarise(quote) {
  const lastDay = new Date(quote.createdAt.getTime() + 29 * 24 * 60 * 60 * 1000);
  return `Quote ${quote.id}: £${(quote.premiumPence / 100).toFixed(2)} a year, valid until ${lastDay.toISOString().slice(0, 10)}`;
}

